solution.source:
@startuml
layout portrait
interface Tile {
  + draw(area, canvas)
  + photoCount(): int
}
class Photo {
  - name
  + draw(area, canvas)
  + photoCount(): int
}
class Split {
  - direction
  + add(tile: Tile)
  + draw(area, canvas)
  + photoCount(): int
}
class ShareButton {
  - selection: Tile
  + press(): canvas
}
ShareButton --> Tile : selection
Photo ..|> Tile
Split ..|> Tile
Split o--> "*" Tile : tiles
@enduml

