@startuml
layout portrait
class Client
interface Component {
  + operation()
}
class Leaf {
  + operation()
}
class Composite {
  + add(child: Component)
  + operation()
}
Client --> Component : uses
Leaf ..|> Component
Composite ..|> Component
Composite o--> "*" Component : children
@enduml
